COMPONENT [dpr-canvas-scaling]: HiDPI-crisp canvas: size the backing store to devicePixelRatio then scale the 2D context so you draw in CSS pixels and retina displays are not blurry
```js
// HiDPI-crisp canvas: size the backing store to devicePixelRatio, then
// scale the 2D context so all drawing uses CSS pixels and stays sharp.
function fitCanvas(canvas, cssW, cssH) {
  const dpr = window.devicePixelRatio || 1;
  canvas.style.width = cssW + "px";
  canvas.style.height = cssH + "px";
  canvas.width = Math.round(cssW * dpr);
  canvas.height = Math.round(cssH * dpr);
  const ctx = canvas.getContext("2d");
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  return ctx;
}
// const ctx = fitCanvas(document.getElementById("c"), 800, 600);
// Draw using 0..800 / 0..600 coords; backing store is dpr-scaled.
```

COMPONENT [inventory-slot-grid]: Fixed-slot inventory with item stacking, a selected slot, add/use helpers, and overflow reporting when there is no room.
```js
function makeInventory(slots = 12, stackMax = 99) {
  return { items: Array(slots).fill(null), sel: 0, stackMax };
}
function addItem(inv, id, qty = 1) {                 // returns leftover (overflow)
  for (const s of inv.items) if (s && s.id === id && s.qty < inv.stackMax) {
    const add = Math.min(qty, inv.stackMax - s.qty); s.qty += add; qty -= add;
    if (qty === 0) return 0;
  }
  for (let i = 0; i < inv.items.length; i++) if (!inv.items[i]) {
    const add = Math.min(qty, inv.stackMax); inv.items[i] = { id, qty: add }; qty -= add;
    if (qty === 0) return 0;
  }
  return qty;
}
function selected(inv) { return inv.items[inv.sel]; }
function useSelected(inv) { const s = selected(inv); if (s && --s.qty <= 0) inv.items[inv.sel] = null; return s; }
```
